<meta name="component" content="ArenaStatesPage">

<!-- Every arena component in every fixture state it declares, a captioned
     cell each, in a grid that scrolls (docs/ui.md §6.1). -->
<scroll id="Page">
  <div id="Cells">
    <section class="cell" data-member="roster"><span class="caption">{$captions.roster_default}</span><div class="stage"><ArenaRoster title={$roster_default.title} selected={$roster_default.selected} characters={$roster_default_characters} players={$roster_default_players} /></div></section>
    <section class="cell" data-member="roster"><span class="caption">{$captions.roster_empty}</span><div class="stage"><ArenaRoster title={$roster_empty.title} selected={$roster_empty.selected} characters={$roster_empty_characters} players={$roster_empty_players} /></div></section>
