    <section class="cell" data-member="draft"><span class="caption">{$captions.draft_ban}</span><div class="stage"><ArenaDraft title={$draft_ban.title} phase={$draft_ban.phase} active={$draft_ban.active} nameA={$draft_ban.nameA} nameB={$draft_ban.nameB} timeLeft={$draft_ban.timeLeft} timeTotal={$draft_ban.timeTotal} canConfirm={$draft_ban.canConfirm} slots={$draft_ban_slots} /></div></section>
