    <section class="cell" data-member="round-hud"><span class="caption">{$captions.roundHud_critical}</span><div class="stage"><ArenaRoundHud round={$roundHud_critical.round} rounds={$roundHud_critical.rounds} nameA={$roundHud_critical.nameA} nameB={$roundHud_critical.nameB} scoreA={$roundHud_critical.scoreA} scoreB={$roundHud_critical.scoreB} localTeam={$roundHud_critical.localTeam} timeLeft={$roundHud_critical.timeLeft} timeTotal={$roundHud_critical.timeTotal} outcome={$roundHud_critical.outcome} at={$roundHud_critical.at} detail={$roundHud_critical.detail} /></div></section>
